                accent_counts[block[1][1]] += 1
    accent = accent_counts.most_common(1)[0][0] if accent_counts else 7
    # Find rectangular outlines: same non-background color along all four edges,
    # with background in their interior; fill interior with accent.
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
